{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "A close anilino-pyrimidine/piperazine kinase-inhibitor analogue achieved 77% absolute oral bioavailability in healthy volunteers in the fed state, showing that large, basic, high-TPSA molecules of this class can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The same scaffold gave 57% absolute oral bioavailability in the fasted state, indicating that the high absorption is not dependent on food co-administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Brigatinib, a structurally similar anilino-pyrimidine with piperazine/piperidine solubilizing groups, has approximately 46% oral bioavailability in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Trametinib, a fused heterocyclic anilino drug with high TPSA and multiple hydrogen-bond acceptors, has 72% oral bioavailability in the fasted state, demonstrating that such physicochemical features do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Brepocitinib, a heteroaryl amine with piperidine and amide functionality, has 75% absolute oral bioavailability in humans, further supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A structurally related piperazine-containing fused heterocycle has oral bioavailability of approximately 20–25%, still at or above the 20% threshold and providing a lower-bound supportive anchor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Consistent high-transfer human absolute bioavailability data (46–77%) from close structural analogues with the same anilino-pyrimidine/piperazine kinase-inhibitor features outweigh the physicochemical low-absorption prior; the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "The impact of the secondary piperazine NH versus N-methyl piperazine analogues on permeability or efflux is not directly quantified.",
    "Low-F records (vinpocetine, TFMPP, mCPP, cadazolid) have zero transferability and are structurally unrelated, so they do not inform the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

